import java.util.InputMismatchException;import java.util.Scanner;
public class DivisionExceptionDemo {public static void main(String[] args){Scanner sc=new Scanner(System.in);try{System.out.print("Enter first integer: ");int a=sc.nextInt();System.out.print("Enter second integer: ");int b=sc.nextInt();System.out.println("Result: "+a/b);}catch(ArithmeticException e){System.out.println("Error: Division by zero is not allowed.");}catch(InputMismatchException e){System.out.println("Error: Please enter valid integers only.");}finally{System.out.println("Program execution completed.");sc.close();}}}
